<?php if ($d['adding']): ?><script>
(function () {
  var f = document.getElementById('cd-addf'), sel = {};
  f.addEventListener('click', function (e) { var b = e.target.closest('.cd-av'); if (!b) return; var id = b.getAttribute('data-oid'); if (sel[id]) delete sel[id]; else sel[id] = +b.getAttribute('data-w'); b.classList.toggle('on', !!sel[id]); b.querySelector('.sl-chk').classList.toggle('on', !!sel[id]); var ids = Object.keys(sel), w = ids.reduce(function (s, k) { return s + sel[k]; }, 0); document.getElementById('cd-ids').value = ids.join(','); document.getElementById('cd-sel').textContent = ids.length ? ids.length + ' selected · ' + w.toFixed(1) : 'Nothing selected'; });
  f.addEventListener('sl:done', function (e) { if (e.detail && e.detail.success) location.href = <?= json_encode($self) ?>; });
  document.getElementById('cd-q').addEventListener('keydown', function (e) { if (e.key === 'Enter') { e.preventDefault(); location.href = <?= json_encode($self . '&add=1&q=') ?> + encodeURIComponent(this.value); } });
})();
